// Nó Code "Montar jogos do dia" (modo: Run Once for All Items)
// Junta os jogos da football-data e da ESPN (Europa League, NFL e NBA), converte para o horário de Brasília,
// fica só com os jogos da pauta de hoje e marca o peso de cada time a partir da tabela Times.
// No fim, pendura em cada jogo os desfalques (lesionados e suspensos) de cada time:
// NFL e NBA pela ESPN, futebol pela API-Football.

const TZ = 'America/Sao_Paulo';
const agora = $now.setZone(TZ);
const hoje = agora.toFormat('yyyy-MM-dd');
// A pauta cobre de hoje às 6h até amanhã às 6h: jogo da NBA às 00h30 de Brasília ainda é "de hoje".
const inicioPauta = agora.startOf('day').plus({ hours: 6 });
const fimPauta = inicioPauta.plus({ days: 1 });

// O nó do Airtable devolve os campos soltos no item; este helper aceita os dois formatos.
const campos = (item) => ({ id: item.json.id, ...(item.json.fields ?? item.json) });

// Campeonatos ativos, indexados pelo código usado na API
const campeonatos = {};
for (const c of $('Campeonatos').all().map(campos)) {
  if (c.Ativo) campeonatos[c['Código']] = c;
}

// Peso dos times: cada grafia em "Nomes nas APIs" aponta para o time
const semAcento = (s) => (s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
const times = new Map();
for (const t of $('Times').all().map(campos)) {
  for (const nome of (t['Nomes nas APIs'] ?? '').split(',')) {
    if (nome.trim()) times.set(semAcento(nome), { nome: t.Nome, peso: t.Peso ?? 1 });
  }
}
const acharTime = (...nomes) => {
  for (const n of nomes) {
    const t = times.get(semAcento(n));
    if (t) return t;
  }
  return null;
};

const jogos = [];
const adicionar = (codigo, jogo) => {
  const c = campeonatos[codigo];
  if (!c) return;
  const inicio = DateTime.fromISO(jogo.utc, { zone: 'utc' }).setZone(TZ);
  if (inicio < inicioPauta || inicio >= fimPauta) return;
  const pesoMandante = jogo.timeMandante?.peso ?? 0;
  const pesoVisitante = jogo.timeVisitante?.peso ?? 0;
  jogos.push({
    id: jogo.id,
    campeonato: c.Nome,
    campeonatoId: c.id,
    codigo,
    bloco: c.Bloco,
    ordem: c.Ordem ?? 99,
    todosOsJogos: !!c['Todos os jogos'],
    limiteNota4: c['Limite nota 4'] ?? 0,
    horario: inicio.toFormat('HH:mm'),
    horarioISO: inicio.toISO(),
    utc: jogo.utc,
    mandante: jogo.mandante,
    visitante: jogo.visitante,
    // Todas as grafias conhecidas de cada time, para casar com os nomes da API-Football
    nomesMandante: [...new Set([jogo.mandante, ...(jogo.nomesMandante ?? []), jogo.timeMandante?.nome].filter(Boolean))],
    nomesVisitante: [...new Set([jogo.visitante, ...(jogo.nomesVisitante ?? []), jogo.timeVisitante?.nome].filter(Boolean))],
    idMandante: jogo.idMandante ?? null,
    idVisitante: jogo.idVisitante ?? null,
    pesoMandante,
    pesoVisitante,
    pesoTotal: pesoMandante + pesoVisitante,
    status: jogo.status,
    fase: jogo.fase ?? null,
    rodada: jogo.rodada ?? null,
    campanhaMandante: jogo.campanhaMandante ?? null,
    campanhaVisitante: jogo.campanhaVisitante ?? null,
    extras: jogo.extras ?? null,
  });
};

// football-data.org
const statusFD = {
  SCHEDULED: 'Agendado', TIMED: 'Agendado', IN_PLAY: 'Ao vivo', PAUSED: 'Ao vivo',
  FINISHED: 'Encerrado', AWARDED: 'Encerrado', POSTPONED: 'Adiado', SUSPENDED: 'Adiado', CANCELLED: 'Cancelado',
};
for (const m of $('football-data').first().json.matches ?? []) {
  adicionar(m.competition.code, {
    id: `fd-${m.id}`,
    utc: m.utcDate,
    mandante: m.homeTeam.shortName ?? m.homeTeam.name,
    visitante: m.awayTeam.shortName ?? m.awayTeam.name,
    idMandante: m.homeTeam.id,
    idVisitante: m.awayTeam.id,
    nomesMandante: [m.homeTeam.name, m.homeTeam.shortName],
    nomesVisitante: [m.awayTeam.name, m.awayTeam.shortName],
    timeMandante: acharTime(m.homeTeam.name, m.homeTeam.shortName),
    timeVisitante: acharTime(m.awayTeam.name, m.awayTeam.shortName),
    status: statusFD[m.status] ?? m.status,
    fase: m.stage,
    rodada: m.matchday,
  });
}

// ESPN: Europa League (nó "ESPN"), NFL (nó "ESPN NFL") e NBA (nó "ESPN NBA"). O código do campeonato
// é o slug da liga na ESPN (uefa.europa, nfl, nba). Se uma chamada falhar, o fluxo segue sem esses jogos.
const statusESPN = (s) => {
  if (s.name === 'STATUS_POSTPONED') return 'Adiado';
  if (s.name === 'STATUS_CANCELED') return 'Cancelado';
  return { pre: 'Agendado', in: 'Ao vivo', post: 'Encerrado' }[s.state] ?? s.name;
};
const lerESPN = (no, slugPadrao) => {
  const espn = $(no).first().json;
  for (const ev of espn.events ?? []) {
    const comp = ev.competitions[0];
    const lados = comp.competitors;
    const casa = lados.find((l) => l.homeAway === 'home');
    const fora = lados.find((l) => l.homeAway === 'away');
    // Contexto extra que a ESPN já entrega no placar (útil para o Gemini na NFL)
    const tv = (comp.broadcasts ?? []).flatMap((b) => b.names ?? []).join(', ');
    const local = comp.venue?.address;
    const extras = [
      ...(comp.notes ?? []).map((n) => n.headline),
      comp.neutralSite && local?.country ? `Campo neutro: ${[local.city, local.country].filter(Boolean).join(', ')}` : null,
      tv ? `TV nos EUA: ${tv}` : null,
    ].filter(Boolean);
    adicionar(espn.leagues?.[0]?.slug ?? slugPadrao, {
      id: `espn-${ev.id}`,
      utc: ev.date,
      mandante: casa.team.shortDisplayName ?? casa.team.displayName,
      visitante: fora.team.shortDisplayName ?? fora.team.displayName,
      idMandante: casa.team.id,
      idVisitante: fora.team.id,
      nomesMandante: [casa.team.displayName, casa.team.shortDisplayName],
      nomesVisitante: [fora.team.displayName, fora.team.shortDisplayName],
      timeMandante: acharTime(casa.team.displayName, casa.team.shortDisplayName),
      timeVisitante: acharTime(fora.team.displayName, fora.team.shortDisplayName),
      campanhaMandante: casa.records?.[0]?.summary,
      campanhaVisitante: fora.records?.[0]?.summary,
      status: statusESPN(ev.status.type),
      fase: espn.leagues?.[0]?.season?.type?.name ?? null,
      rodada: espn.week?.number ?? null,
      extras: extras.join(' · ') || null,
    });
  }
  return !!espn.error;
};
const espnFalhou = lerESPN('ESPN', 'uefa.europa');
const nflFalhou = lerESPN('ESPN NFL', 'nfl');
const nbaFalhou = lerESPN('ESPN NBA', 'nba');

// ---------- Desfalques ----------
// Cada desfalque vira { nome, texto, fora }: "texto" é o que vai para o Gemini e "fora" separa quem
// certamente não joga (fora, lista de lesionados, suspenso) de quem é dúvida.
const MAX_POR_TIME = 12;
const statusEmPortugues = {
  'Out': 'fora',
  'Injured Reserve': 'fora (lista de lesionados)',
  'Out For Season': 'fora da temporada',
  'Suspension': 'suspenso',
  'Doubtful': 'dúvida, improvável',
  'Questionable': 'dúvida',
  'Day-To-Day': 'dia a dia',
  'Missing Fixture': 'fora',
};
const estaFora = (status) => /^fora|suspenso/.test(status);
// "Rest" é jogador poupado (comum na pré-temporada da NBA): traduzido, o Gemini entende que é desfalque de verdade
const motivoEmPortugues = { Rest: 'poupado (descanso)', Undisclosed: 'não divulgado' };
const desfalque = (nome, posicao, status, motivo) => ({
  nome,
  texto: `${nome}${posicao ? ` (${posicao})` : ''}: ${[status, motivoEmPortugues[motivo] ?? motivo].filter(Boolean).join(', ')}`,
  fora: estaFora(status),
});
// Primeiro quem é notícia nesta rodada (fora, suspenso, dúvida); quem está fora há tempo (lista de lesionados) vai por último
const prioridade = (d) => (/lesionados|temporada/.test(d.texto) ? 2 : d.fora ? 0 : 1);
// A API-Football repete o mesmo jogador no retorno: tira as duplicatas antes de cortar em MAX_POR_TIME
const ordenar = (lista) => [...new Map(lista.map((d) => [d.texto, d])).values()]
  .sort((a, b) => prioridade(a) - prioridade(b)).slice(0, MAX_POR_TIME);

// ESPN (NFL e NBA): uma chamada traz a liga inteira, agrupada por time. O id do time é o mesmo do placar.
const lesoesESPN = (no, liga) => {
  const resposta = $(no).first().json;
  for (const time of resposta.injuries ?? []) {
    const lista = (time.injuries ?? [])
      .filter((l) => l.status && l.status !== 'Active')
      .map((l) => {
        const status = statusEmPortugues[l.status] ?? l.status.toLowerCase();
        const motivo = [l.details?.type, l.details?.detail].filter((d) => d && d !== 'Not Specified').join(' ');
        return desfalque(l.athlete?.displayName, l.athlete?.position?.abbreviation, status, motivo);
      });
    for (const j of jogos.filter((x) => x.codigo === liga)) {
      if (String(j.idMandante) === String(time.id)) j.desfalquesMandante = ordenar(lista);
      if (String(j.idVisitante) === String(time.id)) j.desfalquesVisitante = ordenar(lista);
    }
  }
  return !resposta.injuries;
};
const nflLesoesFalhou = jogos.some((j) => j.codigo === 'nfl') && lesoesESPN('ESPN NFL lesões', 'nfl');
const nbaLesoesFalhou = jogos.some((j) => j.codigo === 'nba') && lesoesESPN('ESPN NBA lesões', 'nba');

// API-Football (futebol): a chamada traz os desfalques de todos os jogos do dia, no mundo inteiro.
// Os ids não batem com os da football-data/ESPN, então o jogo é achado pelo horário de início
// e o time pelo nome (grafias da tabela Times ou palavras em comum: "Man United" ~ "Manchester United").
const GENERICAS = new Set(['fc', 'cf', 'ac', 'sc', 'afc', 'cd', 'ca', 'ec', 'se', 'rc', 'ssc', 'as', 'club', 'clube', 'de', 'da', 'do', 'the', 'calcio', 'futebol', 'football', 'esporte']);
const palavras = (s) => semAcento(s).replace(/[^a-z0-9]+/g, ' ').split(' ').filter((p) => p.length > 1 && !GENERICAS.has(p));
const parecido = (nomeApi, nomes) => {
  const canonico = acharTime(nomeApi)?.nome;
  if (canonico && nomes.includes(canonico)) return 1;
  const a = palavras(nomeApi);
  let melhor = 0;
  for (const n of nomes) {
    const b = palavras(n);
    if (!a.length || !b.length) continue;
    // "Man" casa com "Manchester": conta prefixos com pelo menos 3 letras
    const comuns = a.filter((p) => b.some((q) => p === q || (Math.min(p.length, q.length) >= 3 && (p.startsWith(q) || q.startsWith(p)))));
    melhor = Math.max(melhor, comuns.length / Math.min(a.length, b.length));
  }
  return melhor;
};

const futebol = jogos.filter((j) => !['nfl', 'nba'].includes(j.codigo));
const apiFootball = $('API-Football lesões').first().json;
const errosApi = apiFootball.errors && !Array.isArray(apiFootball.errors) ? Object.values(apiFootball.errors) : [];
const erroFutebol = !futebol.length ? null
  : apiFootball.error ? (apiFootball.error.message ?? String(apiFootball.error))
  : errosApi.length ? errosApi.join(' ')
  : null;
for (const l of apiFootball.response ?? []) {
  const inicio = (l.fixture?.timestamp ?? 0) * 1000;
  for (const j of futebol) {
    if (Math.abs(DateTime.fromISO(j.utc).toMillis() - inicio) > 15 * 60 * 1000) continue;
    const casa = parecido(l.team.name, j.nomesMandante);
    const fora = parecido(l.team.name, j.nomesVisitante);
    if (Math.max(casa, fora) < 0.5) continue;
    const lado = casa >= fora ? 'desfalquesMandante' : 'desfalquesVisitante';
    const status = statusEmPortugues[l.player.type] ?? String(l.player.type ?? '').toLowerCase();
    (j[lado] ??= []).push(desfalque(l.player.name, null, status, l.player.reason));
    break;
  }
}
for (const j of futebol) {
  if (j.desfalquesMandante) j.desfalquesMandante = ordenar(j.desfalquesMandante);
  if (j.desfalquesVisitante) j.desfalquesVisitante = ordenar(j.desfalquesVisitante);
}

jogos.sort((a, b) => a.ordem - b.ordem || a.horarioISO.localeCompare(b.horarioISO));

return [{
  json: {
    data: hoje, total: jogos.length, jogos, espnFalhou, nflFalhou, nbaFalhou,
    nflLesoesFalhou, nbaLesoesFalhou, erroFutebol,
  },
}];

// Nó Code "Ligas com classificação" (modo: Run Once for All Items)
// Gera um item por campeonato que tem jogo hoje e tem tabela de classificação.
// Mata-mata (ex.: Libertadores na fase final) não tem tabela, então fica de fora.
// Ligue "Always Output Data" nas Settings: assim o fluxo segue mesmo sem nenhuma liga.

const { jogos } = $('Montar jogos do dia').first().json;
const fasesComTabela = ['REGULAR_SEASON', 'LEAGUE_STAGE', 'GROUP_STAGE'];

const codigos = new Set(
  jogos
    .filter((j) => j.id.startsWith('fd-') && fasesComTabela.includes(j.fase))
    .map((j) => j.codigo),
);

return [...codigos].map((codigo) => ({ json: { codigo } }));

// Nó Code "Preparar pedido ao Gemini" (modo: Run Once for All Items)
// Junta cada jogo com a posição dos times na tabela e os desfalques, e monta o corpo da chamada ao Gemini,
// pedindo a resposta em JSON com formato fixo (responseSchema).

const { data, jogos } = $('Montar jogos do dia').first().json;

// Posição de cada time por campeonato (o Bayern tem uma posição na Bundesliga e outra na Champions)
const tabela = new Map();
for (const item of $('Classificação').all()) {
  const codigo = item.json.competition?.code;
  for (const s of item.json.standings ?? []) {
    if (s.type !== 'TOTAL') continue;
    for (const linha of s.table) {
      tabela.set(`${codigo}:${linha.team.id}`, `${linha.position}º de ${s.table.length}, ${linha.points} pts em ${linha.playedGames} jogos`);
    }
  }
}

const lista = jogos.map((j) => ({
  id: j.id,
  campeonato: j.campeonato,
  fase: j.fase ?? undefined,
  rodada: j.rodada ?? undefined,
  horario: j.horario,
  mandante: j.mandante,
  visitante: j.visitante,
  tabelaMandante: tabela.get(`${j.codigo}:${j.idMandante}`),
  tabelaVisitante: tabela.get(`${j.codigo}:${j.idVisitante}`),
  campanhaMandante: j.campanhaMandante ?? undefined,
  campanhaVisitante: j.campanhaVisitante ?? undefined,
  extras: j.extras ?? undefined,
  desfalquesMandante: j.desfalquesMandante?.map((d) => d.texto),
  desfalquesVisitante: j.desfalquesVisitante?.map((d) => d.texto),
  pesoMandante: j.pesoMandante,
  pesoVisitante: j.pesoVisitante,
}));

const instrucoes = `Você é editor de pauta de um canal de esportes brasileiro.
Para cada jogo, dê uma nota de relevância de 1 a 5 para o público brasileiro e escreva um briefing.

Critérios da nota:
5 = jogão: clássico ou rivalidade histórica, confronto direto entre times do topo da tabela, decisão (mata-mata, final) ou time brasileiro decidindo título ou vaga.
4 = jogo bom: pelo menos um time gigante (peso 3) ou confronto entre times da parte de cima da tabela.
3 = interessante só para quem acompanha o campeonato.
2 = jogo comum.
1 = pouco relevante.

O peso dos times vem de uma lista mantida pela produção: 3 = gigante, 2 = forte, 0 = sem destaque.

Jogos da NFL (futebol americano) usam os mesmos números, com estes critérios:
5 = horário nobre (Sunday Night, Monday Night ou Thursday Night, pelo horário de Brasília à noite), jogo no Brasil ou fora dos EUA, playoff/Super Bowl, ou confronto entre duas campanhas fortes.
4 = time popular no Brasil (peso 3) ou duelo de divisão com as duas equipes brigando por vaga.
3 ou menos = jogo comum da rodada de domingo.
Na NFL, "campanha" é vitórias-derrotas(-empates) na temporada e "rodada" é a semana (week). Nada de tabela de classificação.

Jogos da NBA (basquete) também usam os mesmos números:
5 = clássico (Lakers x Celtics, Knicks x Celtics, Lakers x Warriors etc.), jogo fora dos EUA, playoff/play-in/finais, ou confronto entre duas campanhas fortes.
4 = pelo menos um time popular no Brasil (peso 3), jogo de abertura da temporada ou de Natal, ou duelo direto entre times do topo da conferência.
3 ou menos = jogo comum da rodada (tem jogo quase todo dia).
Pré-temporada (fase "Preseason") vale menos: no máximo 4, e só com time peso 3 ou clássico. Na NBA, "campanha" é vitórias-derrotas na fase indicada.

Regras:
- Use os dados de tabela e campanha fornecidos. Não invente resultados recentes, artilheiros, técnicos ou escalações.
- "desfalquesMandante" e "desfalquesVisitante" listam lesionados e suspensos informados pelas fontes ("Nome (posição): situação, motivo"). Use só esses: não cite nenhum outro jogador como desfalque. Se o jogo não tiver essa lista, não fale de desfalques.
- A ausência de uma estrela ou titular importante pode mudar a nota e merece entrar no briefing. Reserva, jogador de rotação ou quem está fora há meses não muda nada.
- "desfalques": os até 3 desfalques que importam para o jogo, no formato "Nome (Time, situação em português)", separados por "; ". Ex.: "Patrick Mahomes (Chiefs, dúvida); Travis Kelce (Chiefs, fora)". Jogador conhecido do público (estrela, All-Star, titular de time grande) entra mesmo que seja só dúvida ou descanso: "descanso" (poupado) é desfalque de verdade, principalmente na pré-temporada da NBA, e deve aparecer como "poupado". Devolva "" só se a lista estiver vazia ou tiver apenas reservas desconhecidos.
- Brasileirão e Libertadores interessam mais ao público: na dúvida, suba a nota.
- "motivo": uma frase curta explicando a nota.
- "briefing": no máximo 2 frases, em português do Brasil, dizendo o que está em jogo. Tom de jornalista esportivo, sem exagero.
- Avalie todos os jogos recebidos e devolva cada um com o mesmo id.`;

const body = {
  systemInstruction: { parts: [{ text: instrucoes }] },
  contents: [{ role: 'user', parts: [{ text: `Jogos de ${data}:\n${JSON.stringify(lista, null, 1)}` }] }],
  generationConfig: {
    temperature: 0.4,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        jogos: {
          type: 'ARRAY',
          items: {
            type: 'OBJECT',
            properties: {
              id: { type: 'STRING' },
              nota: { type: 'INTEGER' },
              motivo: { type: 'STRING' },
              briefing: { type: 'STRING' },
              desfalques: { type: 'STRING' },
            },
            required: ['id', 'nota', 'motivo', 'briefing', 'desfalques'],
          },
        },
      },
      required: ['jogos'],
    },
  },
};

return [{ json: { totalJogos: jogos.length, body } }];

// Nó Code "Selecionar jogos" (modo: Run Once for All Items)
// Lê as notas do Gemini e aplica as regras do resumo:
// - campeonatos com "Todos os jogos" marcado: entram todos;
// - nos outros: nota 5 entra sempre, nota 4 entra até o "Limite nota 4" do campeonato.
// Se o Gemini falhar, a nota sai do peso dos times e o resumo é enviado mesmo assim (sem briefing nem desfalques).

const { data, jogos } = $('Montar jogos do dia').first().json;

let avaliacoes = [];
let llmFalhou = false;
try {
  const resposta = $('Gemini').first().json;
  const texto = resposta.candidates[0].content.parts.map((p) => p.text ?? '').join('');
  avaliacoes = JSON.parse(texto).jogos;
} catch (e) {
  llmFalhou = jogos.length > 0;
}
const porId = new Map(avaliacoes.map((a) => [a.id, a]));

const notaPeloPeso = (j) => {
  if (j.pesoTotal >= 5) return 5;
  if (j.pesoTotal >= 4 || Math.max(j.pesoMandante, j.pesoVisitante) === 3) return 4;
  if (j.pesoTotal >= 2) return 3;
  return 2;
};

// Só aceita desfalque que veio das fontes: se o Gemini citar alguém fora da lista do jogo, o nome cai.
const semAcento = (s) => (s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
const conferirDesfalques = (texto, j) => {
  const conhecidos = [...(j.desfalquesMandante ?? []), ...(j.desfalquesVisitante ?? [])].map((d) => semAcento(d.nome));
  return String(texto ?? '')
    .split(';')
    .map((s) => s.trim())
    .filter((s) => s && conhecidos.includes(semAcento(s.split('(')[0])))
    .join('; ');
};

const avaliados = jogos.map((j) => {
  const a = porId.get(j.id);
  const nota = Number.isInteger(a?.nota) ? Math.min(5, Math.max(1, a.nota)) : notaPeloPeso(j);
  return {
    ...j,
    nota,
    motivo: a?.motivo ?? 'Nota calculada pelo peso dos times (sem LLM).',
    briefing: a?.briefing ?? '',
    desfalques: conferirDesfalques(a?.desfalques, j),
  };
});

const porCampeonato = new Map();
for (const j of avaliados) {
  if (!porCampeonato.has(j.codigo)) porCampeonato.set(j.codigo, []);
  porCampeonato.get(j.codigo).push(j);
}

const escolhidos = [];
for (const lista of porCampeonato.values()) {
  if (lista[0].todosOsJogos) {
    escolhidos.push(...lista);
    continue;
  }
  escolhidos.push(...lista.filter((j) => j.nota === 5));
  const nota4 = lista
    .filter((j) => j.nota === 4)
    .sort((a, b) => b.pesoTotal - a.pesoTotal || a.horarioISO.localeCompare(b.horarioISO));
  escolhidos.push(...nota4.slice(0, lista[0].limiteNota4));
}

escolhidos.sort((a, b) => a.ordem - b.ordem || a.horarioISO.localeCompare(b.horarioISO));

return [{
  json: {
    data,
    llmFalhou,
    totalAnalisados: jogos.length,
    totalEscolhidos: escolhidos.length,
    jogos: escolhidos,
  },
}];

// Nó Code "Separar jogos" (modo: Run Once for All Items)
// Transforma a lista de jogos escolhidos em um item por jogo,
// com as chaves iguais aos nomes das colunas da tabela Jogos no Airtable.

const { data, jogos } = $('Adicionar transmissão').first().json;

return jogos.map((j) => ({
  json: {
    ID: j.id,
    Data: data, // dia da pauta (um jogo às 00h30 continua na pauta de ontem)
    'Horário': j.horarioISO,
    Campeonato: [j.campeonatoId],
    Mandante: j.mandante,
    Visitante: j.visitante,
    Status: j.status,
    Nota: j.nota,
    'Por que a nota': j.motivo,
    Briefing: j.briefing,
    Desfalques: j.desfalques,
    'Transmissão': j.transmissao,
  },
}));

// Nó Code "Montar mensagem" (modo: Run Once for All Items)
// Monta o resumo do dia em HTML do Telegram: uma mensagem só, separada por blocos (Brasil, Copas, Europa, NFL, NBA).
// O Telegram aceita até 4096 caracteres por mensagem; só se passar disso o texto é dividido em mais de uma.

const LIMITE = 3900;
const { data, jogos, llmFalhou, totalAnalisados, transmissaoFalhou } = $('Adicionar transmissão').first().json;
const { espnFalhou, nflFalhou, nbaFalhou, nflLesoesFalhou, nbaLesoesFalhou, erroFutebol } = $('Montar jogos do dia').first().json;

const html = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const selo = (nota) => (nota === 5 ? '🔥' : nota === 4 ? '⭐' : '▫️');
const dia = DateTime.fromISO(data).setLocale('pt-BR').toFormat("cccc, dd/MM");

const blocos = [
  { nome: 'Brasil', titulo: '🇧🇷 <b>BRASIL</b>' },
  { nome: 'Copas', titulo: '🏆 <b>COPAS</b>' },
  { nome: 'Europa', titulo: '🌍 <b>EUROPA</b>' },
  { nome: 'NFL', titulo: '🏈 <b>NFL</b>' },
  { nome: 'NBA', titulo: '🏀 <b>NBA</b>' },
];

const cabecalho = jogos.length
  ? `📅 <b>Pauta de hoje: ${html(dia)}</b>\n${jogos.length} de ${totalAnalisados} jogos selecionados · 🔥 jogão · ⭐ bom jogo`
  : `📅 <b>Pauta de hoje: ${html(dia)}</b>\nHoje não tem jogos dos campeonatos acompanhados.`;

const avisos = [];
if (llmFalhou) avisos.push('⚠️ O Gemini não respondeu hoje: notas calculadas pelo peso dos times, sem briefing.');
if (espnFalhou) avisos.push('⚠️ A ESPN não respondeu: a Europa League pode estar faltando.');
if (nflFalhou) avisos.push('⚠️ A ESPN não respondeu: os jogos da NFL podem estar faltando.');
if (nbaFalhou) avisos.push('⚠️ A ESPN não respondeu: os jogos da NBA podem estar faltando.');
if (nflLesoesFalhou) avisos.push('⚠️ A ESPN não mandou as lesões da NFL: desfalques ficaram de fora.');
if (nbaLesoesFalhou) avisos.push('⚠️ A ESPN não mandou as lesões da NBA: desfalques ficaram de fora.');
if (transmissaoFalhou) avisos.push('⚠️ A 365Scores não respondeu: a transmissão dos jogos ficou de fora.');
if (erroFutebol) avisos.push(`⚠️ API-Football falhou (${html(erroFutebol.slice(0, 150))}): desfalques do futebol ficaram de fora.`);

const mensagens = [];
let atual = cabecalho;
const fechar = () => { if (atual.trim()) mensagens.push(atual); atual = ''; };
const adicionar = (trecho) => {
  if (atual && (atual + '\n\n' + trecho).length > LIMITE) fechar();
  atual = atual ? `${atual}\n\n${trecho}` : trecho;
};

for (const bloco of blocos) {
  const doBloco = jogos.filter((j) => j.bloco === bloco.nome);
  if (!doBloco.length) continue;
  adicionar(bloco.titulo);
  let campeonatoAtual = null;
  for (const j of doBloco) {
    const linhas = [];
    // Subtítulo do campeonato, menos quando repete o nome do bloco (NFL, NBA)
    if (j.campeonato !== campeonatoAtual) {
      if (j.campeonato !== bloco.nome) linhas.push(`<u>${html(j.campeonato)}</u>`);
      campeonatoAtual = j.campeonato;
    }
    linhas.push(`${selo(j.nota)} <b>${j.horario}</b> · ${html(j.mandante)} x ${html(j.visitante)}`);
    if (j.transmissao) linhas.push(`📺 ${html(j.transmissao)}`);
    if (j.briefing) linhas.push(`<i>${html(j.briefing)}</i>`);
    for (const d of String(j.desfalques ?? '').split(';').map((s) => s.trim()).filter(Boolean)) linhas.push(`🚑 ${html(d)}`);
    adicionar(linhas.join('\n'));
  }
}
if (avisos.length) adicionar(avisos.join('\n'));
fechar();

return mensagens.map((texto) => ({ json: { texto } }));

// Nó Code "Pedidos 365Scores" (modo: Run Once for All Items)
// Gera um pedido à lista de jogos da 365Scores para cada esporte que tem jogo selecionado na pauta.
// A 365Scores separa por esporte: 1 = futebol, 2 = basquete, 6 = futebol americano.
// A pauta vai de hoje às 6h até amanhã às 6h, então a busca cobre os dois dias.
// Ligue "Always Output Data" nas Settings: assim o fluxo segue até a mensagem mesmo sem jogo selecionado.

const { data, jogos } = $('Selecionar jogos').first().json;
const ESPORTE_365 = { nfl: 6, nba: 2 }; // os demais campeonatos são de futebol

const dia = DateTime.fromISO(data);
const esportes = new Set(jogos.map((j) => ESPORTE_365[j.codigo] ?? 1));

return [...esportes].map((esporte) => ({
  json: {
    esporte,
    inicio: dia.toFormat('dd/MM/yyyy'),
    fim: dia.plus({ days: 1 }).toFormat('dd/MM/yyyy'),
  },
}));

// Nó Code "Casar transmissões" (modo: Run Once for All Items)
// Acha cada jogo selecionado na lista da 365Scores. Os ids não batem com os da football-data/ESPN,
// então o jogo é achado pelo esporte, pelo horário de início (±15 min) e pelo nome dos times
// (grafias da tabela Times ou palavras em comum, a mesma regra usada com a API-Football).
// Só sai um item por jogo que a 365Scores marca com transmissão (hasTVNetworks): os canais vêm no nó seguinte.
// Ligue "Always Output Data" nas Settings: sem nenhum jogo casado, o fluxo segue até a mensagem.

const { jogos } = $('Selecionar jogos').first().json;
const ESPORTE_365 = { nfl: 6, nba: 2 };
const TOLERANCIA = 15 * 60 * 1000;

const campos = (item) => ({ id: item.json.id, ...(item.json.fields ?? item.json) });
const semAcento = (s) => (s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
const times = new Map();
for (const t of $('Times').all().map(campos)) {
  for (const nome of (t['Nomes nas APIs'] ?? '').split(',')) {
    if (nome.trim()) times.set(semAcento(nome), t.Nome);
  }
}

const GENERICAS = new Set(['fc', 'cf', 'ac', 'sc', 'afc', 'cd', 'ca', 'ec', 'se', 'rc', 'ssc', 'as', 'club', 'clube', 'de', 'da', 'do', 'the', 'calcio', 'futebol', 'football', 'esporte']);
const palavras = (s) => semAcento(s).replace(/[^a-z0-9]+/g, ' ').split(' ').filter((p) => p.length > 1 && !GENERICAS.has(p));
const parecido = (nomeApi, nomes) => {
  const canonico = times.get(semAcento(nomeApi));
  if (canonico && nomes.includes(canonico)) return 1;
  const a = palavras(nomeApi);
  let melhor = 0;
  for (const n of nomes) {
    const b = palavras(n);
    if (!a.length || !b.length) continue;
    const comuns = a.filter((p) => b.some((q) => p === q || (Math.min(p.length, q.length) >= 3 && (p.startsWith(q) || q.startsWith(p)))));
    melhor = Math.max(melhor, comuns.length / Math.min(a.length, b.length));
  }
  return melhor;
};

const lista = $('365Scores jogos').all().flatMap((i) => i.json.games ?? []);

const casados = [];
for (const j of jogos) {
  const esporte = ESPORTE_365[j.codigo] ?? 1;
  const inicio = DateTime.fromISO(j.utc).toMillis();
  let melhor = null;
  let pontos = 0;
  for (const g of lista) {
    if (g.sportId !== esporte) continue;
    if (Math.abs(DateTime.fromISO(g.startTime).toMillis() - inicio) > TOLERANCIA) continue;
    const casa = g.homeCompetitor?.name;
    const fora = g.awayCompetitor?.name;
    // Soma dos dois times; testa também invertido, caso uma fonte troque mandante e visitante
    const p = Math.max(
      parecido(casa, j.nomesMandante) + parecido(fora, j.nomesVisitante),
      parecido(casa, j.nomesVisitante) + parecido(fora, j.nomesMandante),
    );
    if (p > pontos) { melhor = g; pontos = p; }
  }
  // Pelo menos um time inteiro reconhecido (o horário já filtrou quase tudo)
  if (melhor && pontos >= 1 && melhor.hasTVNetworks) {
    casados.push({ json: { jogoId: j.id, gameId: melhor.id } });
  }
}

return casados;

// Nó Code "Adicionar transmissão" (modo: Run Once for All Items)
// Devolve a seleção do nó "Selecionar jogos" com o campo "transmissao" em cada jogo:
// os canais brasileiros (userCountryId=21) que a 365Scores lista para a partida, separados por vírgula.
// Se a 365Scores falhar, os jogos seguem sem transmissão e a mensagem avisa.

const selecao = $('Selecionar jogos').first().json;

const respostasLista = $('365Scores jogos').all().map((i) => i.json);
const casados = $('Casar transmissões').all().map((i) => i.json).filter((c) => c.gameId);
const detalhes = casados.length ? $('365Scores transmissão').all().map((i) => i.json) : [];

const canais = new Map();
for (const d of detalhes) {
  if (!d.game?.id) continue;
  const nomes = (d.game.tvNetworks ?? []).map((t) => String(t.name ?? '').trim()).filter(Boolean);
  canais.set(d.game.id, [...new Set(nomes)].join(', '));
}
const gamePorJogo = new Map(casados.map((c) => [c.jogoId, c.gameId]));

const transmissaoFalhou = selecao.jogos.length > 0 && (
  respostasLista.some((r) => r.error || !r.games) || detalhes.some((d) => d.error)
);

return [{
  json: {
    ...selecao,
    transmissaoFalhou,
    jogos: selecao.jogos.map((j) => ({ ...j, transmissao: canais.get(gamePorJogo.get(j.id)) ?? '' })),
  },
}];
